package br.com.pelotavision;
import org.opencv.core.*;import org.opencv.imgproc.*;import org.opencv.imgcodecs.*;import java.nio.file.*;import java.util.*;import java.io.*;
public class DetailNative {
 static void check(boolean v,String m){if(!v)throw new AssertionError(m);}
 static String n(double d){return Double.isFinite(d)?Double.toString(d):"null";}
 public static void main(String[] args)throws Exception{
  nu.pattern.OpenCV.loadLocally();Core.setNumThreads(2);FsrcnnUpscaler sr=new FsrcnnUpscaler(args[2]);Mat tiny=new Mat(29,31,CvType.CV_8UC1,new Scalar(120));Mat enlarged=sr.upsample(tiny);check(enlarged.rows()==58&&enlarged.cols()==62,"SR shape");double mean=Core.mean(enlarged.submat(10,48,10,52)).val[0];check(mean>100&&mean<140,"SR normalization/bias "+mean);System.out.println("PASS actual FSRCNN network x2 dimensions and flat-field normalization: "+mean);tiny.release();enlarged.release();
  Mat g=new Mat(1200,1600,CvType.CV_8UC1,new Scalar(35));List<Point> centers=new ArrayList<>();for(int y:new int[]{160,440,720,1000})for(int x:new int[]{140,400,660,920,1180,1440}){centers.add(new Point(x,y));Imgproc.circle(g,new Point(x,y),26,new Scalar(200),-1,Imgproc.LINE_AA,0);}byte[] before=new byte[1600*1200];g.get(0,0,before);DetailGeometry geometry=new DetailGeometry(1600,1200,800,600,.5,.5,0,0,1,null);DetectionTuner.Option option=new DetectionTuner.Option(1,75,false);
  TilePlan.Tile sampleTile=TilePlan.create(1600,1200,false).get(0);Mat sample=g.submat(0,640,0,640);DetectionTuner.Report nativeSearch=DetectionTuner.search(sample,option,DetectionAssessment.Context.tile(null,1600,1200,null,5,geometry,sampleTile),()->false,(a,b,c)->{},120000);check(nativeSearch.trials.size()==24,"Native search incomplete");for(DetectionTuner.Trial trial:nativeSearch.trials)check(trial.error==null&&trial.result.width==640,"Search used preview dimensions or mismatched window");sample.release();System.out.println("PASS all 24 configurations on original-resolution representative tile.");
  DetailedAnalysis.Output known=DetailedAnalysis.run(g,geometry,option,true,null,null,1600,1200,5,null,50,()->false,(a,b,c)->{});System.out.println("Synthetic tiles="+known.report.tiles+" count="+known.result.circles.size());check(known.result.circles.size()==24,"Synthetic count changed; inspect segmentation");for(Point p:centers){int hits=0;for(PelletDetector.Detection d:known.result.circles)if(Math.hypot(d.x-p.x*.5,d.y-p.y*.5)<3)hits++;check(hits==1,"Seam missing/duplicate");}byte[] after=before.clone();g.get(0,0,after);check(Arrays.equals(before,after),"Original modified by enhancement");System.out.println("PASS 24 known pellets across "+known.report.tiles+" native tiles, unique centers and original pixels unchanged.");
  try{DetailedAnalysis.run(g,geometry,option,false,null,null,1600,1200,5,null,50,()->true,(a,b,c)->{});throw new AssertionError("Cancellation returned partial output");}catch(java.util.concurrent.CancellationException expected){System.out.println("PASS cancellation throws; no partial result returned.");}g.release();
  Mat full=Imgcodecs.imread(args[0],0),crop=full.submat(340,940,440,860).clone();DetailGeometry map=new DetailGeometry(420,600,full.cols(),full.rows(),1,1,440,340,1,new InterestRegion(InterestRegion.Shape.RECTANGLE,440,340,860,940));CrackModel model=new CrackModel(new FileInputStream(args[1]));
  DetailedAnalysis.Output real=DetailedAnalysis.run(crop,map,new DetectionTuner.Option(1,90,true),true,sr,null,full.cols(),full.rows(),5,model,50,()->false,(a,b,c)->System.out.println(a+"/"+b+" "+c));for(PelletDetector.Detection d:real.result.circles)check(map.region.includes(d),"Out of ROI");check(real.cracks.entries.size()==real.result.circles.size(),"Crack count mapping");
  PelletDetector.Result result=real.result;CrackAnalysis cracks=real.cracks;StringBuilder s=new StringBuilder("{\"width\":"+result.width+",\"height\":"+result.height+",\"method\":\""+result.method+"\",\"tiles\":"+real.report.tiles+",\"baseline\":"+real.report.baselineCount+",\"duration_ms\":"+real.report.durationMs+",\"treatments\":"+Arrays.toString(real.report.treatments)+",\"native_test\":\"OpenCV desktop 4.9; Android 4.12 differs\",\"accuracy_validated\":false,\"objects\":[");
  for(int i=0;i<result.circles.size();i++){PelletDetector.Detection d=result.circles.get(i);CrackAnalysis.Entry c=cracks.entries.get(i);if(i>0)s.append(',');s.append(String.format(Locale.ROOT,"{\"x\":%.8f,\"y\":%.8f,\"a\":%.8f,\"b\":%.8f,\"radius\":%.8f,\"angle\":%.8f,\"partial\":%s,\"review\":%s,\"fitted\":%s,\"support\":%s,\"rms\":%s,\"roundness\":%.8f,\"crack_x\":%.8f,\"crack_y\":%.8f,\"crack_radius\":%.8f,\"crack_review\":%s,\"crack_status\":\"%s\",\"crack_score\":%s,\"crack_runs\":[",d.x,d.y,d.semiMajor,d.semiMinor,d.radius,d.angleDeg,d.partial,d.needsReview,d.ellipseFitted,n(d.fitSupport),n(d.fitRms),d.roundness,d.crackX,d.crackY,d.crackRadius,d.crackNeedsReview,c.status,n(c.modelScore)));float[] runs=c.markedRuns();for(int k=0;k<runs.length;k++){if(k>0)s.append(',');s.append(runs[k]);}s.append("]}");}s.append("]}");Path path=Path.of(args[3]);Files.createDirectories(path.getParent());Files.writeString(path,s);System.out.println("PASS real ROI: "+result.circles.size()+" markers, baseline="+real.report.baselineCount+", "+real.report.tiles+" blocks, SR compared. No ground-truth accuracy claim.");crop.release();full.release();
 }
}
